let route='home',mobileNav=false,filterTopic='all',filters={section:'all',part:'all',topic:'all',difficulty:'all',count:20,unseen:false},listFilter='all',listSearch='',listLimit=40;
let Q=new Map(),G=new Map(),loaded=new Set(),loading=new Map(),busy=false,activeTranscript=null,lastResult=null,reviewDetail=null,currentAudioGroup=null,currentQuestionStart=now();
function notify(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastHandle);toastHandle=setTimeout(()=>el.classList.remove('visible'),3500)}
