function normalizeState(s){
if(!s||s.formatVersion!==1||!Array.isArray(s.attempts)||!Array.isArray(s.sessions))throw new Error('學習紀錄格式不正確');
const validTime=x=>Number.isFinite(x)&&x>=0&&x<8640000000000000;
const r={formatVersion:1,noteDraftEpoch:safeId(s.noteDraftEpoch)?s.noteDraftEpoch:'initial',settings:{fontScale:[1,1.1,1.2].includes(s.settings?.fontScale)?s.settings.fontScale:1,translation:false},attempts:[],stats:{},stars:{},notes:{},sessions:[],active:null,importedPacks:[],lastBackup:validTime(s.lastBackup)?s.lastBackup:null};
const ids=new Set();for(const a of s.attempts){if(!a||!safeId(a.id)||!safeId(a.questionId)||!safeId(a.testId)||!validTime(a.at)||typeof a.correct!=='boolean'||!['A','B','C','D',null].includes(a.selected)||![1,2,3,4,5,6,7].includes(a.part)||!Object.hasOwn(TOPICS,a.topic))throw new Error('作答紀錄有無效欄位');if(!ids.has(a.id)){r.attempts.push({id:a.id,questionId:a.questionId,testId:a.testId,revision:Number.isSafeInteger(a.revision)&&a.revision>0?a.revision:1,correctAnswer:['A','B','C','D'].includes(a.correctAnswer)?a.correctAnswer:undefined,part:a.part,topic:a.topic,selected:a.selected,correct:a.correct,at:a.at,seconds:Number.isFinite(a.seconds)?Math.max(0,Math.min(3600,a.seconds)):0});ids.add(a.id)}}
r.attempts.sort((a,b)=>a.at-b.at);for(const a of r.attempts){const st=r.stats[a.questionId]||(r.stats[a.questionId]={attempts:0,wrong:0,streak:0});st.attempts++;st.wrong+=a.correct?0:1;st.streak=a.correct?st.streak+1:0;st.lastCorrect=a.correct;st.lastAt=a.at;st.testId=a.testId;st.part=a.part;st.topic=a.topic;st.due=a.at+(a.correct?(st.streak<2?3:7):1)*86400000;st.needsReview=st.wrong>0&&st.streak<2}
for(const[k,v]of Object.entries(s.stars||{}))if(safeId(k)&&v)r.stars[k]=true;
for(const[k,v]of Object.entries(s.notes||{}))if(safeId(k)&&typeof v==='string')r.notes[k]=v.slice(0,20000);
function session(x,active=false){if(!x||!safeId(x.id)||!['practice','exam'].includes(x.mode)||typeof x.title!=='string'||!Array.isArray(x.questionIds)||!x.questionIds.length||x.questionIds.length>5000||!x.questionIds.every(safeId)||new Set(x.questionIds).size!==x.questionIds.length||!validTime(x.startedAt)||!x.answers||typeof x.answers!=='object')throw new Error('練習進度格式不正確');const answerIds=new Set(x.questionIds),answers={},submitted={};for(const[k,v]of Object.entries(x.answers)){if(!answerIds.has(k)||!['A','B','C','D'].includes(v))throw new Error('練習選項格式不正確');answers[k]=v}for(const[k,v]of Object.entries(x.submitted||{}))if(answerIds.has(k)&&v===true)submitted[k]=true;
const y={id:x.id,title:x.title.slice(0,250),mode:x.mode,questionIds:x.questionIds.slice(),answers,submitted,startedAt:x.startedAt};
if(active){if(!Array.isArray(x.testIds)||!x.testIds.every(safeId)||!Number.isSafeInteger(x.index)||x.index<0||x.index>=x.questionIds.length||(x.mode==='exam'&&!validTime(x.deadline)))throw new Error('未完成進度格式不正確');y.testIds=x.testIds.slice();y.index=x.index;y.deadline=x.mode==='exam'?x.deadline:null}else{if(!Number.isSafeInteger(x.correct)||!Number.isSafeInteger(x.total)||!Number.isSafeInteger(x.answered)||x.total!==x.questionIds.length||x.correct<0||x.correct>x.total||x.answered<0||x.answered>x.total||!validTime(x.finishedAt))throw new Error('成績欄位必須是有效數字');y.correct=x.correct;y.total=x.total;y.answered=x.answered;y.finishedAt=x.finishedAt}return y}
r.sessions=s.sessions.map(x=>session(x));if(s.active)r.active=session(s.active,true);
const testIds=new Set();for(const p of s.importedPacks||[]){validatePack(p);if(testIds.has(p.testId)||catalog.tests.some(t=>t.id===p.testId))throw new Error('備份含重複或內建題庫 ID');testIds.add(p.testId);r.importedPacks.push(p)}return r}

async function initStorage(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('shift-english-lab-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('kv');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('資料庫被另一個分頁占用'))});const stored=await new Promise((resolve,reject)=>{const r=db.transaction('kv').objectStore('kv').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(stored)state=normalizeState(stored);storageMode='indexeddb';db.onversionchange=()=>{db.close();storageMode='memory';notify('儲存環境已更新，請匯出紀錄並重新開啟。')};await persist();return}catch(e){console.warn('IndexedDB unavailable',e)}try{localStorage.setItem('shift-probe','1');localStorage.removeItem('shift-probe');const raw=localStorage.getItem('shift-english-lab-v1');if(raw)state=normalizeState(JSON.parse(raw));storageMode='localstorage'}catch(e){storageMode='memory'}}
function persist(){if(storageMode==='loading'||storageMode==='memory')return Promise.resolve();const snapshot=JSON.stringify(state);saveQueue=saveQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(storageMode==='indexeddb'&&db){const tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(JSON.parse(snapshot),'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('儲存中斷'))}else{try{localStorage.setItem('shift-english-lab-v1',snapshot);resolve()}catch(e){reject(e)}}})).catch(e=>{console.error(e);storageMode='memory';notify('瀏覽器無法保存紀錄，請到資料管理匯出備份。');updateStorageBadge()});return saveQueue}
function readNoteDraft(){try{const raw=localStorage.getItem(NOTE_DRAFT_KEY);return raw?JSON.parse(raw):null}catch(e){return null}}
function removeNoteDraft(token){try{if(readNoteDraft()?.token===token)localStorage.removeItem(NOTE_DRAFT_KEY)}catch(e){}}
function noteStatusText(id){return noteStatuses.get(id)||(storageMode==='memory'?'暫存模式，請匯出備份':state.notes[id]?'已保存於目前瀏覽器':'輸入後自動儲存於目前瀏覽器')}
function setNoteStatus(id,text){noteStatuses.set(id,text);const el=document.getElementById('note-save-status'),input=document.getElementById('question-note');if(el&&input?.dataset.id===id)el.textContent=text}
function clearNoteDraft(){noteGeneration++;noteTokens.clear();noteStatuses.clear();state.noteDraftEpoch=uid();try{localStorage.removeItem(NOTE_DRAFT_KEY)}catch(e){}}
function saveNoteInput(id,text){
if(!safeId(id))return;
const token=uid(),generation=noteGeneration,draft={version:1,token,epoch:state.noteDraftEpoch||'initial',questionId:id,text:String(text).slice(0,20000),at:now()};
state.notes[id]=draft.text;noteTokens.set(id,token);let cached=false;
try{localStorage.setItem(NOTE_DRAFT_KEY,JSON.stringify(draft));cached=true}catch(e){}
setNoteStatus(id,'儲存中…');
persist().then(()=>{if(generation!==noteGeneration||noteTokens.get(id)!==token)return;if(storageMode==='indexeddb'||storageMode==='localstorage'){removeNoteDraft(token);setNoteStatus(id,'已保存於目前瀏覽器')}else setNoteStatus(id,cached?'草稿已暫存，請匯出備份':'尚未持久保存，請匯出備份')});
}
async function restoreNoteDraft(){
const draft=readNoteDraft();
if(!draft||draft.version!==1||!safeId(draft.token)||!safeId(draft.questionId)||typeof draft.text!=='string'||draft.text.length>20000)return false;
if(draft.epoch!==(state.noteDraftEpoch||'initial')){removeNoteDraft(draft.token);return false}
const generation=noteGeneration;state.notes[draft.questionId]=draft.text;noteTokens.set(draft.questionId,draft.token);setNoteStatus(draft.questionId,'正在恢復筆記…');
await persist();
if(generation!==noteGeneration||noteTokens.get(draft.questionId)!==draft.token)return false;
if(storageMode==='indexeddb'||storageMode==='localstorage'){removeNoteDraft(draft.token);setNoteStatus(draft.questionId,'已保存於目前瀏覽器')}else setNoteStatus(draft.questionId,'草稿已恢復，請匯出備份');
return true;
}
function updateStorageBadge(){const b=document.getElementById('storage-badge');if(b){b.innerHTML=icon(storageMode==='memory'?'info':'shield')+(storageMode==='memory'?'暫存模式・請備份':'紀錄儲存在本機');b.classList.toggle('warn',storageMode==='memory')}}
function validatePack(p){
if(!p||p.schemaVersion!==1||!safeId(p.testId)||!Array.isArray(p.questions)||!Array.isArray(p.groups)||p.questions.length<1||p.questions.length>5000)throw new Error('題庫格式不符，需 schemaVersion: 1 與 questions/groups。');
const gs=new Map(),ids=new Set(),numbers=new Set();
for(const g of p.groups){
if(!g||!safeId(g.id)||gs.has(g.id)||g.testId!==p.testId||![1,2,3,4,5,6,7].includes(g.part)||typeof g.passage!=='string'||typeof g.passageZh!=='string')throw new Error('題組內容、所屬題庫或 ID 無效：'+(g?.id||'未知'));
if(g.audio&&!safeMedia(g.audio))throw new Error('音檔路徑不安全或不受支援');
if(g.image&&!safeMedia(g.image))throw new Error('圖片路徑不安全或不受支援');
gs.set(g.id,g);
}
for(const q of p.questions){
if(!q||!safeId(q.id)||ids.has(q.id)||q.testId!==p.testId||![1,2,3,4,5,6,7].includes(q.part)||typeof q.prompt!=='string'||typeof q.promptZh!=='string'||typeof q.explanationZh!=='string'||!q.explanationZh.trim()||!Object.hasOwn(TOPICS,q.topic)||!Object.hasOwn(DIFFICULTY,q.difficulty)||!Array.isArray(q.options)||q.options.length!==(q.part===2?3:4))throw new Error('題目格式無效：'+(q?.id||'未知'));
if(!Number.isSafeInteger(q.number)||q.number<1||numbers.has(q.number))throw new Error('題號必須是同一題庫內不重複的正整數：'+q.id);
if(q.groupId&&!gs.has(q.groupId))throw new Error('缺少題組：'+q.groupId);
if(q.groupId&&gs.get(q.groupId).part!==q.part)throw new Error('題目與題組的 Part 不一致：'+q.id);
if(q.tags&&(!Array.isArray(q.tags)||q.tags.some(t=>typeof t!=='string')))throw new Error('題目標籤格式無效：'+q.id);
const opts=new Set();
for(const o of q.options){if(!o||!['A','B','C','D'].includes(o.id)||opts.has(o.id)||typeof o.text!=='string'||typeof o.zh!=='string'||typeof o.whyZh!=='string'||!o.whyZh.trim())throw new Error('選項翻譯或解析不完整：'+q.id);opts.add(o.id)}
if(!opts.has(q.answer))throw new Error('答案不存在：'+q.id);
if(q.vocabulary&&!Array.isArray(q.vocabulary))throw new Error('詞彙格式無效');
ids.add(q.id);numbers.add(q.number);
}
return p;
}
function registerPack(p){validatePack(p);for(const g of p.groups)G.set(g.id,g);for(const q of p.questions)Q.set(q.id,q);loaded.add(p.testId)}
async function loadTest(id){if(loaded.has(id))return;if(loading.has(id))return loading.get(id);const local=state.importedPacks.find(p=>p.testId===id);if(local){registerPack(local);return}const t=catalog.tests.find(t=>t.id===id);if(!t)throw new Error('找不到題庫 '+id);const promise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=t.path;script.onload=()=>{try{const p=window.SHIFT_PACKS.find(p=>p.testId===id);if(!p)throw new Error('題庫檔缺少內容');registerPack(p);resolve()}catch(e){reject(e)}};script.onerror=()=>{script.remove();reject(new Error('無法載入 '+t.path+'。請先完整解壓縮整個資料夾，再開啟 index.html。'))};document.head.append(script)});loading.set(id,promise);try{await promise}finally{loading.delete(id)}}
