function allTests(){return catalog.tests.concat(state.importedPacks.filter(p=>!catalog.tests.some(t=>t.id===p.testId)).map(p=>({id:p.testId,title:p.title||p.testId,subtitle:'自訂題庫',reading:p.questions.filter(q=>q.part>4).length,listening:p.questions.filter(q=>q.part<5).length,imported:true})))}
